/** Isolated localhost dedicated-server review. Not part of the distributed mod. */
public final class Stage20ENetworkServer implements ModInitializer {
 private static final Path DIR=Path.of(System.getProperty("witchersbestiary.stage20eOutput","../stage20e-network"));private final String[] names={"WBOne","WBTwo"};private final UUID[] contracts=new UUID[2];private final BlockPos[] homes=new BlockPos[2],targets=new BlockPos[2];private final long[] commands=new long[2];private final int[] xp=new int[2],emeralds=new int[2];private final Map<String,Object> results=new LinkedHashMap<>();private int phase,age,phaseAge;private long nonce=System.currentTimeMillis(),start;private BlockPos board,explore;private String[] signatures=new String[2];private boolean resumed,rewardResume;private double mspt;private int samples;private long sampleStart;
 private ServerPlayerEntity player(MinecraftServer s,int i){return s.getPlayerManager().getPlayer(names[i]);}
 private ContractInstance instance(MinecraftServer s,int i){return contracts[i]==null?null:ContractState.get(s).find(contracts[i]);}
 private void assertTrue(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 private void change(int next){results.put("phase_"+phase,"PASS");phase=next;phaseAge=0;try{write(DIR.resolve("scenario-results.json"),results);write(DIR.resolve("heartbeat.json"),Map.of("phase",phase,"age",age));}catch(Exception e){throw new RuntimeException(e);}}
 private JsonObject read(Path p)throws Exception{return JsonParser.parseString(Files.readString(p)).getAsJsonObject();}
 private void write(Path p,Object value)throws Exception{var temp=p.resolveSibling(p.getFileName()+".tmp");Files.writeString(temp,new GsonBuilder().setPrettyPrinting().create().toJson(value));Files.move(temp,p,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
 private void issue(int i,String action,Object...pairs)throws Exception{var j=new JsonObject();j.addProperty("nonce",++nonce);commands[i]=nonce;j.addProperty("action",action);for(int n=0;n<pairs.length;n+=2){var key=pairs[n].toString();var value=pairs[n+1];if(value instanceof Number number)j.addProperty(key,number);else j.addProperty(key,value.toString());}write(DIR.resolve(names[i]+".command.json"),j);}
 private boolean ack(int i)throws Exception{var file=DIR.resolve(names[i]+".reply.json");return Files.exists(file)&&read(file).get("nonce").getAsLong()==commands[i];}
 private JsonObject response(int i)throws Exception{return read(DIR.resolve(names[i]+".reply.json"));}
 private void waitClients()throws Exception{for(int i=0;i<2;i++)issue(i,"wait");}
 private void open(MinecraftServer s,int i,String action)throws Exception{var p=player(s,i);p.changeGameMode(GameMode.CREATIVE);p.setInvulnerable(true);p.setNoGravity(true);p.teleport(s.getOverworld(),board.getX()+(i==0?-2:2),board.getY(),board.getZ()-3,0,0);s.getOverworld().getBlockState(board).onUse(s.getOverworld(),p,new BlockHitResult(board.toCenterPos(),Direction.NORTH,board,false));issue(i,action,"definition",i==0?ProceduralHunts.id("ghoul"):GraveDevourer.ID);}
 private BlockPos findBoard(ServerWorld w,BlockPos center){for(int radius=0;radius<=36;radius+=3)for(int dx=-radius;dx<=radius;dx+=3)for(int dz=-radius;dz<=radius;dz+=3){int x=center.getX()+dx,z=center.getZ()+dz;var chunk=w.getChunkManager().getWorldChunk(x>>4,z>>4);if(chunk==null||w.getChunkManager().getWorldChunk((x-2)>>4,(z-2)>>4)==null||w.getChunkManager().getWorldChunk((x+2)>>4,(z+2)>>4)==null)continue;var at=new BlockPos(x,chunk.sampleHeightmap(Heightmap.Type.MOTION_BLOCKING_NO_LEAVES,x&15,z&15)+1,z);if(NoticeBoardBlock.place(w,at,Direction.NORTH))return at;}return null;}
 private BlockPos forestDirection(ServerWorld w,BlockPos origin){var sampler=w.getChunkManager().getNoiseConfig().getMultiNoiseSampler();for(int n=0;n<48;n++){double angle=n*.4;int x=origin.getX()+(int)(240*Math.cos(angle)),z=origin.getZ()+(int)(240*Math.sin(angle));if(w.getChunkManager().getChunkGenerator().getBiomeSource().getBiome(x>>2,16,z>>2,sampler).isIn(BiomeTags.IS_FOREST))return new BlockPos(x,180,z);}return origin.add(240,100,0);}
 private void study(MinecraftServer s,int i)throws Exception{var c=instance(s,i);var clue=c.investigation.next();assertTrue(clue!=null,"Missing next clue "+i);var p=player(s,i);p.changeGameMode(GameMode.CREATIVE);p.setInvulnerable(true);p.setNoGravity(true);p.teleport(s.getOverworld(),clue.position.getX()+.5,clue.position.getY(),clue.position.getZ()-2,0,40);issue(i,"study","progress",c.investigation.current+1);}
 private void resumeFile(MinecraftServer s,String kind)throws Exception{var j=new JsonObject();j.addProperty("kind",kind);j.addProperty("board",board.asLong());var list=new JsonArray();for(int i=0;i<2;i++){var e=new JsonObject();e.addProperty("contract",contracts[i].toString());e.addProperty("signature",instance(s,i).investigation.write().toString());e.addProperty("xp",player(s,i).totalExperience);e.addProperty("emeralds",player(s,i).getInventory().count(Items.EMERALD));list.add(e);}j.add("players",list);write(DIR.resolve("resume.json"),j);write(DIR.resolve("intermediate-results.json"),results);}
 public void onInitialize(){if(!Boolean.getBoolean("witchersbestiary.stage20eServer"))return;try{Files.createDirectories(DIR);}catch(Exception e){throw new RuntimeException(e);}ServerLifecycleEvents.SERVER_STARTED.register(s->{try{start=System.nanoTime();if(Files.exists(DIR.resolve("resume.json"))){var j=read(DIR.resolve("resume.json"));resumed=true;rewardResume=j.get("kind").getAsString().equals("rewarded");board=BlockPos.fromLong(j.get("board").getAsLong());for(int i=0;i<2;i++){var p=j.getAsJsonArray("players").get(i).getAsJsonObject();contracts[i]=UUID.fromString(p.get("contract").getAsString());signatures[i]=p.get("signature").getAsString();xp[i]=p.get("xp").getAsInt();emeralds[i]=p.get("emeralds").getAsInt();}if(Files.exists(DIR.resolve("intermediate-results.json")))results.putAll(new Gson().fromJson(Files.readString(DIR.resolve("intermediate-results.json")),Map.class));}s.getOverworld().getGameRules().get(GameRules.DO_MOB_SPAWNING).set(false,s);s.getOverworld().getGameRules().get(GameRules.SPAWN_CHUNK_RADIUS).set(0,s);write(DIR.resolve("ready.json"),Map.of("resumed",resumed,"rewardResume",rewardResume));}catch(Throwable t){fail(s,t);}});ServerTickEvents.END_SERVER_TICK.register(s->{if(++age>15000){fail(s,new IllegalStateException("Dedicated test 15000-tick limit"));return;}try{tick(s);}catch(Throwable t){fail(s,t);}});}
 private void fail(MinecraftServer s,Throwable t){try{write(DIR.resolve("server-failure.json"),Map.of("phase",phase,"age",age,"error",t.toString(),"stack",Arrays.toString(t.getStackTrace())));}catch(Exception ignored){}s.stop(false);}
 private void tick(MinecraftServer s)throws Exception{phaseAge++;if(phaseAge>2400&&phase!=99)throw new IllegalStateException("Phase timeout: "+phase);var one=player(s,0);var two=player(s,1);if(phase==0){if(one==null||two==null)return;results.put("two_real_network_players",true);results.put("normal_world_seed",202001);if(resumed){for(int i=0;i<2;i++)assertTrue(instance(s,i)!=null&&instance(s,i).investigation.write().toString().equals(signatures[i]),"Disk route signature unchanged after JVM restart "+i);results.put(rewardResume?"rewarded_dedicated_restart":"tracking_dedicated_restart",true);if(rewardResume){for(int i=0;i<2;i++){assertTrue(instance(s,i).status()==ContractInstance.Status.REWARDED,"Saved reward state");open(s,i,"replayClaim");}change(90);}else{for(int i=0;i<2;i++){if(instance(s,i).investigation.next()!=null)study(s,i);else issue(i,"wait");}change(20);}return;}board=findBoard(s.getOverworld(),one.getBlockPos());if(board==null){if(phaseAge>300)throw new IllegalStateException("No safe natural board site loaded");return;}results.put("board_no_terrain_replacement",true);for(int i=0;i<2;i++){player(s,i).getInventory().clear();open(s,i,"accept");}change(1);return;}
  if(phase==1){for(int i=0;i<2;i++){var c=BoardScreenHandler.existing(player(s,i),i==0?ProceduralHunts.id("ghoul"):GraveDevourer.ID);if(c==null)return;contracts[i]=c.id();}results.put("real_board_accept_both",true);explore=forestDirection(s.getOverworld(),board);for(int i=0;i<2;i++){player(s,i).teleport(s.getOverworld(),explore.getX()+i*20,180,explore.getZ(),0,0);issue(i,"wait");}change(2);return;}
  if(phase==2){boolean found=true;for(int i=0;i<2;i++)if(instance(s,i).investigation.stage!=ContractInvestigation.Stage.TRACKING)found=false;if(found){for(int i=0;i<2;i++){assertTrue(instance(s,i).hunt.target==null,"No target before investigation");study(s,i);}results.put("default_radius_loaded_natural_search",true);change(3);return;}if(phaseAge%100==0){for(int i=0;i<2;i++)if(instance(s,i).investigation.stage==ContractInvestigation.Stage.SEARCHING){int step=(phaseAge/100)%6;player(s,i).teleport(s.getOverworld(),explore.getX()+i*20+step*16,180,explore.getZ()+step%2*16,0,0);}}if(phaseAge>1600)throw new IllegalStateException("Bounded natural hunt search did not find both sites");return;}
  if(phase==3){if(instance(s,0).investigation.current<1||instance(s,1).investigation.current<1)return;for(int i=0;i<2;i++)signatures[i]=instance(s,i).investigation.write().toString();issue(0,"forged","clue",instance(s,1).investigation.clues.getFirst().id);change(4);return;}
  if(phase==4){if(!ack(0))return;assertTrue(instance(s,1).investigation.current==1,"Foreign Inspect packet denied");var snapshot=response(0).getAsJsonObject("snapshot");assertTrue(!snapshot.toString().contains(instance(s,1).investigation.clues.getFirst().id.toString()),"Foreign clue absent from actual S2C snapshot");results.put("real_packet_privacy_and_forgery",true);issue(0,"disconnect");change(5);return;}
  if(phase==5){if(one!=null)return;if(instance(s,1).investigation.next()!=null)study(s,1);else issue(1,"wait");change(6);return;}
  if(phase==6){if(instance(s,1).investigation.current<Math.min(2,instance(s,1).investigation.clues.size()))return;results.put("peer_route_clues",instance(s,1).investigation.clues.size());results.put("peer_advanced_while_owner_offline",instance(s,1).investigation.current>1);assertTrue(instance(s,0).investigation.current==1,"Offline owner progress retained while peer advances");issue(0,"wait");change(7);return;}
  if(phase==7){if(one==null)return;assertTrue(instance(s,0).investigation.write().toString().equals(signatures[0]),"Logout/rejoin exact route");results.put("one_logout_peer_continues",true);one.changeGameMode(GameMode.SURVIVAL);one.setInvulnerable(false);one.damage(one.getServerWorld().getDamageSources().genericKill(),100000);issue(0,"respawn");change(8);return;}
  if(phase==8){if(one==null||!ack(0)||one.getHealth()<=0)return;assertTrue(instance(s,0).status()==ContractInstance.Status.ACCEPTED&&instance(s,0).investigation.current==1,"Death/respawn retains investigation");assertTrue(!Investigations.enabled(one.getUuid()),"Death clears senses");results.put("real_player_death_respawn",true);one.changeGameMode(GameMode.CREATIVE);one.setInvulnerable(true);one.setNoGravity(true);one.teleport(s.getWorld(World.NETHER),0,135,0,0,0);issue(0,"dimension","dimension","minecraft:the_nether");change(9);return;}
  if(phase==9){if(!ack(0))return;assertTrue(!response(0).get("senses").getAsBoolean(),"Dimension change clears local senses");one.teleport(s.getOverworld(),board.getX(),board.getY(),board.getZ()-3,0,0);issue(0,"wait");results.put("real_dimension_roundtrip",true);change(10);return;}
  if(phase==10){if(phaseAge<40)return;waitClients();resumeFile(s,"tracking");results.put("first_run_seconds",(System.nanoTime()-start)/1e9);write(DIR.resolve("intermediate-results.json"),results);s.save(false,true,true);s.stop(false);change(99);return;}
  if(phase==20){for(int i=0;i<2;i++){var c=instance(s,i);if(c.investigation.stage==ContractInvestigation.Stage.TRACKING){if(ack(i))study(s,i);return;}if(c.investigation.stage==ContractInvestigation.Stage.LAIR_FOUND){var lair=c.investigation.lair;player(s,i).teleport(s.getOverworld(),lair.getX()+.5,lair.getY(),lair.getZ()+.5,0,0);Investigations.trySpawn(player(s,i),c);return;}}for(int i=0;i<2;i++){assertTrue(instance(s,i).hunt.target!=null,"Both independent targets");var e=s.getOverworld().getEntity(instance(s,i).hunt.target);assertTrue(e!=null,"Loaded target before leave");targets[i]=e.getBlockPos();issue(i,"wait");player(s,i).teleport(s.getOverworld(),board.getX()+2000+i*128,180,board.getZ()+2000,0,0);}assertTrue(!instance(s,0).hunt.target.equals(instance(s,1).hunt.target),"Unique separate targets of same base species");results.put("same_species_distinct_targets",true);change(21);return;}
  if(phase==21){boolean unloaded=true;for(int i=0;i<2;i++)if(s.getOverworld().getEntity(instance(s,i).hunt.target)!=null)unloaded=false;if(unloaded){for(int i=0;i<2;i++){assertTrue(instance(s,i).status()==ContractInstance.Status.ACCEPTED&&!SwampLord.hasBossBar(instance(s,i).hunt.target),"Unload is not death; bar cleaned");player(s,i).teleport(s.getOverworld(),targets[i].getX(),targets[i].getY(),targets[i].getZ()-3,0,0);}results.put("actual_chunk_entity_unload",true);change(22);}else if(phaseAge>800)throw new IllegalStateException("Target chunks did not unload within bounded window");return;}
  if(phase==22){for(int i=0;i<2;i++)if(s.getOverworld().getEntity(instance(s,i).hunt.target)==null)return;results.put("same_uuid_after_chunk_reload",true);for(int i=0;i<2;i++){var p=player(s,i);var boss=(MobEntity)s.getOverworld().getEntity(instance(s,i).hunt.target);p.changeGameMode(GameMode.SURVIVAL);p.setInvulnerable(false);p.setHealth(20);p.equipStack(EquipmentSlot.HEAD,new ItemStack(Items.NETHERITE_HELMET));p.equipStack(EquipmentSlot.CHEST,new ItemStack(Items.NETHERITE_CHESTPLATE));p.equipStack(EquipmentSlot.LEGS,new ItemStack(Items.NETHERITE_LEGGINGS));p.equipStack(EquipmentSlot.FEET,new ItemStack(Items.NETHERITE_BOOTS));p.addStatusEffect(new net.minecraft.entity.effect.StatusEffectInstance(net.minecraft.entity.effect.StatusEffects.REGENERATION,2400,4));p.setStackInHand(Hand.MAIN_HAND,new ItemStack(ModItems.SILVER_WITCHER_SWORD));p.teleport(s.getOverworld(),boss.getX(),boss.getY(),boss.getZ()-2,0,0);boss.setTarget(p);issue(i,"fight","target",boss.getUuid());}sampleStart=System.nanoTime();results.put("heap_before_combat",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());change(23);return;}
  if(phase==23){if(phaseAge>20){var times=s.getTickTimes();mspt+=times[Math.floorMod(s.getTicks()-1,times.length)]/1e6;samples++;}for(int i=0;i<2;i++){var boss=s.getOverworld().getEntity(instance(s,i).hunt.target);var p=player(s,i);if(boss!=null&&boss.isAlive()&&s.getTicks()%20==0&&p.squaredDistanceTo(boss)>9)p.teleport(s.getOverworld(),boss.getX(),boss.getY(),boss.getZ()-2,0,0);}if(instance(s,0).status()!=ContractInstance.Status.COMPLETED||instance(s,1).status()!=ContractInstance.Status.COMPLETED){if(phaseAge>1800)throw new IllegalStateException("Bounded two-client combat did not finish");return;}results.put("actual_combat_both_complete",true);results.put("combat_mean_server_mspt",samples==0?0:mspt/samples);results.put("combat_observed_tps",phaseAge*1e9/(System.nanoTime()-sampleStart));results.put("combat_ticks",phaseAge);for(int i=0;i<2;i++){xp[i]=player(s,i).totalExperience;emeralds[i]=player(s,i).getInventory().count(Items.EMERALD);open(s,i,"claim");}change(24);return;}
  if(phase==24){for(int i=0;i<2;i++)if(instance(s,i).status()!=ContractInstance.Status.REWARDED)return;for(int i=0;i<2;i++){assertTrue(player(s,i).totalExperience==xp[i]+instance(s,i).definition().reward().experience(),"Exact owner XP reward");assertTrue(player(s,i).getInventory().count(Items.EMERALD)==emeralds[i]+instance(s,i).definition().reward().items().getFirst().count(),"Exact owner emerald reward");xp[i]=player(s,i).totalExperience;emeralds[i]=player(s,i).getInventory().count(Items.EMERALD);issue(i,"replayClaim","definition",i==0?ProceduralHunts.id("ghoul"):GraveDevourer.ID);}results.put("both_claims_same_phase",true);change(25);return;}
  if(phase==25){if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++){assertTrue(player(s,i).totalExperience==xp[i]&&player(s,i).getInventory().count(Items.EMERALD)==emeralds[i],"Repeated reward denied");issue(i,"staleClaim");}change(26);return;}
  if(phase==26){if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++)assertTrue(player(s,i).getInventory().count(Items.EMERALD)==emeralds[i],"Stale sync packet denied");results.put("double_and_stale_claim_denied",true);waitClients();resumeFile(s,"rewarded");write(DIR.resolve("intermediate-results.json"),results);s.save(false,true,true);s.stop(false);change(99);return;}
  if(phase==90){if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++)assertTrue(player(s,i).totalExperience==xp[i]&&player(s,i).getInventory().count(Items.EMERALD)==emeralds[i],"Reward remains once after dedicated JVM restart");results.put("post_restart_double_reward_denied",true);results.put("heap_final",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());results.put("complete",true);write(DIR.resolve("complete.json"),results);for(int i=0;i<2;i++)issue(i,"stop");change(91);return;}
  if(phase==91&&phaseAge>60){s.save(false,true,true);s.stop(false);change(99);}
 }
}
